// --- In widget.h --- (Interface)
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Crucial: Destructor is DECLARED but not defined here

    // Move operations must also be handled this way
    Widget(Widget&&) noexcept;
    Widget& operator=(Widget&&) noexcept;

    // Copy operations could be defined similarly if needed

private:
    struct Impl; // Forward-declare the implementation struct
    std::unique_ptr<Impl> pImpl; // Use unique_ptr for Pimpl
};

// --- In widget.cpp --- (Implementation)
#include "widget.h"
#include <string>
#include <vector>

// Full definition of the implementation struct
struct Widget::Impl {
    std::string name;
    std::vector<double> data;
    // ... other private members and helpers
};

// Constructor definition uses make_unique
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}

// Destructor is now DEFINED after Impl is a complete type
Widget::~Widget() = default; // Using '= default' is fine and expressive

// Move operations are also defined here
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;
